-- ======================================================================
-- 本地开发种子数据 012 — 订单与订单明细
-- 目标库：db_order
--
-- 覆盖最近 14 天、10 种订单状态，用于订单页与仪表盘趋势/状态分布。
-- 分区按当前月份动态创建，避免 2026 年数据落入不存在的分区。
-- ======================================================================
BEGIN;

ALTER TABLE ord_order      ADD COLUMN IF NOT EXISTS tenant_id UUID;
ALTER TABLE ord_order_item ADD COLUMN IF NOT EXISTS tenant_id UUID;

DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN -1..1 LOOP
        start_date := (date_trunc('month', CURRENT_DATE) + (i || ' months')::interval)::date;
        end_date := (start_date + INTERVAL '1 month')::date;
        partition_name := 'ord_order_p' || to_char(start_date, 'YYYYMM');
        EXECUTE format(
            'CREATE TABLE IF NOT EXISTS %I PARTITION OF ord_order FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- 种子订单使用固定前缀，重跑时先清理，避免分区表 UNIQUE(order_no, create_time)
-- 在跨天重跑时产生重复行。
DELETE FROM ord_order_item WHERE order_no LIKE 'ORD-2026-10%';
DELETE FROM ord_order WHERE order_no LIKE 'ORD-2026-10%';

